static int blob_has(const char *path, const char *name)
{
    FILE *fp;
    char line[LINE_LEN];
    char row_name[NAME_LEN];
    int id;
    char cls[32];

    fp = fopen(path, "r");
    if (fp == NULL) {
        return 0;
    }
    while (fgets(line, sizeof(line), fp) != NULL) {
        if (strncmp(line, "CALL ", 5) != 0) {
