static int list_has(const char *path, const char *wanted, int table)
{
    FILE *fp = fopen(path, "r");
    char line[LINE_LEN], name[NAME_LEN], cls[32];
    int id, found = 0;
    if (fp == NULL) return 0;
    while (fgets(line, sizeof(line), fp) != NULL) {
        if (table) {
            if (sscanf(line, "CALL %63s %d %31s", name, &id, cls) == 3 &&
                strcmp(cls, "live") == 0 && strcmp(name, wanted) == 0) found = 1;
        } else if (sscanf(line, "%63s %d", name, &id) == 2 &&
                   strcmp(name, wanted) == 0) found = 1;
    }
    fclose(fp);
    return found;
}

static int read_spool_call(const char *path, char *name, size_t cap)
{
    FILE *fp = fopen(path, "r");
    char line[LINE_LEN], extra;
    int n;
    if (fp == NULL) return -1;
    if (fgets(line, sizeof(line), fp) == NULL ||
        sscanf(line, "%63s %c", name, &extra) != 1) { fclose(fp); return -1; }
    n = fgetc(fp);
    fclose(fp);
    if (n != EOF || strlen(name) >= cap) return -1;
    return 0;
}

int cmd_spin(int argc, char **argv)
{
    const char *blob = CAPSET_PATH, *spool = NULL;
    char call[NAME_LEN], stamp[STAMP_LEN + 1], loaded[32];
    int mark;
    FILE *fp;

    if (argc == 3 && strcmp(argv[0], "--blob") == 0) {
        blob = argv[1]; spool = argv[2];
    } else if (argc == 1) {
        spool = argv[0];
    } else {
        fprintf(stderr, "usage: nockreel spin [--blob PATH] SPOOL\n");
        return 2;
    }
    unlink(ACCEPT_PATH);
    unlink(LOADED_SET_PATH);
    if (read_spool_call(spool, call, sizeof(call)) != 0 ||
        !list_has(DESC_PATH, call, 0) ||
        xin_blob(blob, &mark, stamp, sizeof(stamp)) != 0 ||
        !list_has(blob, call, 1)) {
        return 1;
    }
    snprintf(loaded, sizeof(loaded), "table:%s", stamp);
    printf("{\"loaded\":\"%s\",\"status\":\"replayed\",\"call\":\"%s\"}\n",
           loaded, call);
    fp = fopen(LOADED_SET_PATH, "w");
    if (fp == NULL) return 1;
    fprintf(fp, "%s\n", loaded);
    if (fclose(fp) != 0) return 1;
    fp = fopen(ACCEPT_PATH, "w");
    if (fp == NULL) { unlink(LOADED_SET_PATH); return 1; }
    fputs("1\n", fp);
    if (fclose(fp) != 0) { unlink(ACCEPT_PATH); unlink(LOADED_SET_PATH); return 1; }
    (void)mark;
    return 0;
}
